struct {
	Digest         model.Digest          `json:"digest"`
	OverrideDigest model.Digest          `json:"override_digest"`
	Overrides      model.TargetOverrides `json:"overrides"`
	Cohorts        []Cohort              `json:"cohorts"`
	Clusters       []PlannedCluster      `json:"clusters"`
}{plan.PlacementDigest, overrideDigest, plan.Desired.Overrides, plan.Cohorts, plan.Clusters}

struct {
	Action Action    `json:"action"`
	Actor  uuid.UUID `json:"actor"`
	Reason string    `json:"reason"`
	Fence  int64     `json:"fence"`
}{action, actor, reason, fence}

renderVeleroSchedule(VeleroScheduleRender{
	Name:               schedName,
	Namespace:          namespace,
	BackupStorageName:  bslName,
	Cron:               sched.CronExpression,
	IncludedNamespaces: veleroNamespacesFromJSON(sched.IncludedNamespaces),
	ExcludedNamespaces: veleroNamespacesFromJSON(sched.ExcludedNamespaces),
	TTL:                sched.Ttl,
	Labels: map[string]string{
		"astronomer.io/schedule-id": sched.ID.String(),
	},
})

renderVeleroBackup(VeleroBackupRender{
	Name:               backupName,
	Namespace:          namespace,
	BackupStorageName:  bslName,
	IncludedNamespaces: veleroNamespacesFromJSON(backup.IncludedNamespaces),
	ExcludedNamespaces: veleroNamespacesFromJSON(backup.ExcludedNamespaces),
	Labels: map[string]string{
		"astronomer.io/backup-id": backup.ID.String(),
	},
})

directTokenRequest{
	APIVersion: "authentication.k8s.io/v1",
	Kind:       "TokenRequest",
	Spec:       directTokenRequestSpec{ExpirationSeconds: int64(directCredentialTTL / time.Second)},
}

struct {
	SourceID uuid.UUID         `json:"source_id"`
	Type     model.SourceType  `json:"type"`
	URL      string            `json:"url"`
	AuthMode model.AuthMode    `json:"auth_mode"`
	Trust    model.TrustPolicy `json:"trust_policy"`
}{source.ID, model.SourceType(source.SourceType), source.Url, model.AuthMode(source.AuthMode), trust}

